static bool inputCaptureResolveLegacyHcMotionSelector(const MachineIdentity& identity, HcMotionSelectorReceipt& receipt) {
    // Reviewed resource models have one selected owner; a failed new binding
    // cannot fall back to a superseded legacy matrix.
    if (ymcc::hc_model_motion::find(identity.deviceClass)) return false;
    const auto* recipe = ymcc::hc_legacy_motion::find(identity.deviceClass, identity.gyroMatrixId, identity.accelMatrixId);
    if (!identity.resolved || !recipe || recipe->controllerPreferred) return false;
    MachineIdentity resolved = identity; ymccResolveFamily(resolved);
    if (!resolved.resolved || resolved.family != identity.family || resolved.deviceClass != identity.deviceClass ||
        resolved.gyroMatrixId != recipe->gyroMatrixId || resolved.accelMatrixId != recipe->accelMatrixId) return false;
    HcMotionSelectorReceipt selected;
    selected.attempted = true; selected.resolved = true;
    selected.dmiManufacturer = identity.manufacturer; selected.dmiProduct = identity.product;
    selected.dmiSystemProduct = identity.systemProduct; selected.dmiProcessor = identity.processor;
    selected.dmiSystemVersion = identity.systemVersion; selected.nativeFamily = static_cast<int>(identity.family);
    selected.selectorId = recipe->selectorId; selected.deviceClass = identity.deviceClass;
    selected.gyroMatrixId = recipe->gyroMatrixId; selected.accelMatrixId = recipe->accelMatrixId;
    selected.matrixSourceSha256 = recipe->sourceSha256;
    receipt = std::move(selected); return true;
}

