static bool inputCaptureNewHcMotionSelectorBound() {
    const auto* recipe = ymcc::hc_model_motion::find(g_machineIdentity.deviceClass);
    if (!recipe || !g_machineIdentity.resolved || !g_hcMotionSelector.attempted || !g_hcMotionSelector.resolved) return false;
    const YmccFamily expectedFamily = recipe->deviceClass == "HandheldCompanion.Devices.MinisforumV3" ? YmccFamily::Minisforum : recipe->deviceClass.find("HandheldCompanion.Devices.OneX") == 0 ?
        YmccFamily::OneXPlayer : YmccFamily::Ayanero;
    if (g_machineIdentity.family != expectedFamily) return false;
    if (!recipe->identityGyroMatrixId.empty() &&
        (g_hcMotionSelector.nativeFamily != static_cast<int>(g_machineIdentity.family) ||
         g_hcMotionSelector.dmiProcessor != g_machineIdentity.processor ||
         g_hcMotionSelector.dmiSystemVersion != g_machineIdentity.systemVersion)) return false;
    // No DMI I/O, source hashing or re-resolution on the BUS lane. The selected
    // receipt must still match the current model, raw identity and exact recipe.
    return g_hcMotionSelector.selectorId == recipe->selectorId &&
        g_hcMotionSelector.deviceClass == g_machineIdentity.deviceClass &&
        g_hcMotionSelector.dmiManufacturer == g_machineIdentity.manufacturer &&
        g_hcMotionSelector.dmiProduct == g_machineIdentity.product &&
        g_hcMotionSelector.dmiSystemProduct == g_machineIdentity.systemProduct &&
        g_hcMotionSelector.gyroMatrixId == recipe->gyroMatrixId &&
        g_hcMotionSelector.accelMatrixId == recipe->accelMatrixId &&
        g_machineIdentity.gyroMatrixId == ymcc::hc_model_motion::identityGyroId(*recipe) &&
        g_machineIdentity.accelMatrixId == ymcc::hc_model_motion::identityAccelId(*recipe) &&
        g_hcMotionSelector.matrixSourceSha256 == recipe->sourceSha256;
